from flag_gems.runtime import device as runtime_device
from flag_gems.runtime import torch_device_fn
from flag_gems.runtime.backend._ascend.utils import CORE_NUM
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

_MAX_GRID_SIZE = 65535
# Largest class dimension handled by the single-pass tile kernel. Rows keep a
# whole class range in one vector block; wider inputs fall back to the generic
# class-blocked kernel.
_MAX_BLOCK_C = 2048
_MAX_BLOCK_N = 8
# Elements per program. Every element materializes several fp32 temporaries
# (values, z, mask, term, offsets) that the compiler double-buffers, so the
# budget is set by the fp32 working set regardless of the input dtype: 2048
# elements stay inside the 192 KiB unified buffer, 4096 overflows it.
_TILE_ELEMENTS = 2048
_ACC_DTYPE = tl.float32


@libentry()
@triton.jit(do_not_specialize=["N", "C", "margin"])
def multi_margin_loss_backward_kernel(
    grad_output_ptr,
    input_ptr,
    target_ptr,
    weight_ptr,
    grad_input_ptr,
    N,
    C,
    margin,
    P: tl.constexpr,
    REDUCTION: tl.constexpr,
    HAS_WEIGHT: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_C: tl.constexpr,
):
    pid = tl.program_id(0)
    row_stride = tl.num_programs(0) * BLOCK_N
    margin = margin.to(_ACC_DTYPE)
    classes = tl.arange(0, BLOCK_C)[None, :]
    class_mask = classes < C

    row_start = pid * BLOCK_N
    while row_start < N:
        rows = row_start + tl.arange(0, BLOCK_N)[:, None]
        row_mask = rows < N

        target = tl.load(target_ptr + rows, mask=row_mask, other=0).to(tl.int32)
        valid_target = (target >= 0) & (target < C)
        # Clamp instead of device-asserting: an Ascend device assert is not
        # recoverable and the generic op performs the strict host-side check.
        safe_target = tl.where(valid_target, target, 0)

        target_value = tl.load(
            input_ptr + rows * C + safe_target,
            mask=row_mask,
            other=0.0,
        ).to(_ACC_DTYPE)

        if HAS_WEIGHT:
            target_weight = tl.load(
                weight_ptr + safe_target,
                mask=row_mask,
                other=0.0,
            ).to(_ACC_DTYPE)
        else:
            target_weight = tl.full((BLOCK_N, 1), 1.0, _ACC_DTYPE)

        if REDUCTION == 0:
            grad_output = tl.load(
                grad_output_ptr + rows,
                mask=row_mask,
                other=0.0,
            ).to(_ACC_DTYPE)
        else:
            grad_output = tl.load(grad_output_ptr).to(_ACC_DTYPE)

        # Same association order as torch / the generic kernel so the rounding
        # of every element matches to within one fp32 ulp.
        scale = grad_output * target_weight / C.to(_ACC_DTYPE)
        if REDUCTION == 1:
            scale = scale / N.to(_ACC_DTYPE)

        values = tl.load(
            input_ptr + rows * C + classes,
            mask=row_mask & class_mask,
            other=0.0,
        ).to(_ACC_DTYPE)

        z = margin - target_value + values
        active = row_mask & class_mask & valid_target & (classes != safe_target)
        active = active & (z > 0)
        if P == 1:
            grads = tl.where(active, scale, 0.0)
        else:
            grads = tl.where(active, 2.0 * z * scale, 0.0)

        # The target column receives the negative sum of the remaining
        # columns, exactly like the generic kernel's trailing store.
        target_grad = -tl.sum(grads, axis=1)
        grads = tl.where(classes == safe_target, target_grad[:, None], grads)

        tl.store(
            grad_input_ptr + rows * C + classes,
            grads.to(grad_input_ptr.dtype.element_ty),
            mask=row_mask & class_mask,
        )
        row_start += row_stride


def _check_tensor_device(tensor, input, name):
    if tensor.device != input.device:
        raise RuntimeError(
            f"multi_margin_loss_backward: {name} must be on the input device"
        )


def _prepare(grad_output, input, target, p, margin, weight, reduction):
    """Validate inputs with the generic contract, minus the host-sync check."""
    if not isinstance(input, torch.Tensor) or not isinstance(target, torch.Tensor):
        raise TypeError("multi_margin_loss: input and target must be tensors")
    if input.device.type != runtime_device.name:
        raise RuntimeError(
            f"multi_margin_loss: input must be on a {runtime_device.name} device"
        )
    if input.dtype not in (torch.float16, torch.bfloat16, torch.float32):
        raise RuntimeError(
            "multi_margin_loss: input must be float16, bfloat16 or float32"
        )
    if target.dtype != torch.int64:
        raise RuntimeError("multi_margin_loss: target must have dtype int64")
    if target.device != input.device:
        raise RuntimeError(
            "multi_margin_loss: input and target must be on the same device"
        )

    N, C, is_batched = _shape_info(input)
    if is_batched:
        if tuple(target.shape) != (N,):
            raise RuntimeError(
                "multi_margin_loss: target for a 2D input must have shape [N]"
            )
    elif target.dim() > 1 or target.numel() != 1:
        raise RuntimeError(
            "multi_margin_loss: scalar or 1D input requires exactly one target"
        )

    if weight is not None:
        if not isinstance(weight, torch.Tensor):
            raise TypeError("multi_margin_loss: weight must be a tensor or None")
        if tuple(weight.shape) != (C,):
            raise RuntimeError("multi_margin_loss: weight must have shape [C]")
        if weight.dtype != input.dtype:
            raise RuntimeError(
                "multi_margin_loss: weight must have the same dtype as input"
            )
        _check_tensor_device(weight, input, "weight")

    if not isinstance(grad_output, torch.Tensor):
        raise TypeError("multi_margin_loss_backward: grad_output must be a tensor")
    _check_tensor_device(grad_output, input, "grad_output")
    if grad_output.dtype != input.dtype:
        raise RuntimeError(
            "multi_margin_loss_backward: grad_output must have the input dtype"
        )
    if tuple(grad_output.shape) != _output_shape(N, is_batched, reduction):
        raise RuntimeError(
            "multi_margin_loss_backward: grad_output has an invalid shape"
        )

    return (
        input.contiguous(),
        target.contiguous(),
        None if weight is None else weight.contiguous(),
        grad_output.contiguous(),
        N,
        C,
    )


@functools.lru_cache(maxsize=128)
def _tile_config(N, C):
    block_c = triton.next_power_of_2(C)
    block_n = max(1, min(_MAX_BLOCK_N, _TILE_ELEMENTS // block_c, N))
    # Spread the rows over at least ~2 programs per vector core when there are
    # enough rows, so small class counts still fill the device.
    wanted = max(1, triton.cdiv(N, 2 * CORE_NUM))
    block_n = min(block_n, max(1, wanted))
    grid = min(triton.cdiv(N, block_n), _MAX_GRID_SIZE)
    return block_c, block_n, grid


